// Parser for LLVM's ClangFormatStyleOptions.rst.
//
// The document is generated by dump_format_style.py and is very regular:
//
//   .. _Key:
//
//   **Key** (``CppType``) ...
//     docstring, reST, indented 2
//
//     Nested configuration flags:     (only for struct options)
//
//     * ``bool ChildName`` description
//
//   .. _NextKey:
//
// We only need: the key, the C++ type (``deprecated`` marks deprecated
// options), the docstring, nested field types, and enum values.

const ANCHOR_RE = /^\.\. _([A-Za-z][A-Za-z0-9_]*):\s*$/;
const SIGNATURE_RE = /^\*\*([A-Za-z][A-Za-z0-9_]*)\*\* \(``([^`]+)``\)/;
const FIELD_RE = /^\* ``(.+?)``\s?(.*)$/;
const VALUE_RE = /^\* ``([A-Za-z0-9_]+)`` \(in configuration: ``([^`]+)``\)/;

const isBlank = (line) => line.trim() === "";
const indentOf = (line) => line.length - line.trimStart().length;

function trimBlanks(lines) {
  let start = 0;
  let end = lines.length;
  while (start < end && isBlank(lines[start])) start += 1;
  while (end > start && isBlank(lines[end - 1])) end -= 1;
  return lines.slice(start, end);
}

function dedent(lines, width) {
  return lines.map((line) => (isBlank(line) ? "" : line.slice(Math.min(width, indentOf(line)))));
}

function extractEnumValues(lines) {
  const values = [];
  for (let i = 0; i < lines.length; i += 1) {
    if (lines[i].trim() !== "Possible values:") continue;
    const indent = indentOf(lines[i]);
    let j = i + 1;
    while (j < lines.length) {
      const line = lines[j];
      if (isBlank(line)) {
        j += 1;
        continue;
      }
      const lineIndent = indentOf(line);
      if (lineIndent < indent) break;
      const match = VALUE_RE.exec(line.trim());
      if (!match || lineIndent !== indent) {
        j += 1;
        continue;
      }
      const description = [];
      let k = j + 1;
      while (k < lines.length) {
        const next = lines[k];
        if (isBlank(next)) {
          k += 1;
          continue;
        }
        if (indentOf(next) <= indent) break;
        description.push(next.trim());
        k += 1;
      }
      values.push({ value: match[2], description: description.join(" ") });
      j = k;
    }
  }
  return values;
}

function parseFields(lines) {
  const fields = [];
  let current = null;
  for (const line of lines) {
    const match = FIELD_RE.exec(line);
    if (match) {
      const inner = match[1];
      const split = inner.lastIndexOf(" ");
      current = {
        cppType: inner.slice(0, split).trim(),
        name: inner.slice(split + 1).trim(),
        docLines: [],
      };
      fields.push(current);
      if (match[2]) current.docLines.push(match[2]);
      continue;
    }
    if (current) current.docLines.push(line);
  }
  return fields.map((field) => ({
    ...field,
    docLines: trimBlanks(field.docLines),
    enumValues: extractEnumValues(field.docLines),
  }));
}

/**
 * @param {string} text contents of ClangFormatStyleOptions.rst
 * @returns {Map<string, object>} key -> parsed option, insertion order = document order
 */
export function parseRst(text) {
  const lines = text.replace(/\r\n/g, "\n").split("\n");
  const sections = [];
  let current = null;
  for (const line of lines) {
    const match = ANCHOR_RE.exec(line);
    if (match) {
      current = { key: match[1], lines: [] };
      sections.push(current);
    } else if (current) {
      current.lines.push(line);
    }
  }

  const options = new Map();
  for (const section of sections) {
    const signatureIndex = section.lines.findIndex((line) => SIGNATURE_RE.test(line));
    if (signatureIndex === -1) continue;
    const signature = SIGNATURE_RE.exec(section.lines[signatureIndex]);

    let body = dedent(trimBlanks(section.lines.slice(signatureIndex + 1)), 2);

    let fieldStart = body.findIndex((line) => line.trim() === "Nested configuration flags:");
    if (fieldStart === -1) fieldStart = body.length;
    const fields = parseFields(trimBlanks(body.slice(fieldStart + 1)));

    const docBody = body.slice(0, fieldStart);
    const valuesStart = docBody.findIndex((line) => line.trim() === "Possible values:");
    const docLines = trimBlanks(valuesStart === -1 ? docBody : docBody.slice(0, valuesStart));

    options.set(signature[1], {
      key: signature[1],
      cppType: signature[2],
      deprecated: signature[2] === "deprecated",
      docLines,
      fields,
      enumValues: extractEnumValues(docBody),
    });
  }

  return options;
}

// ---------------------------------------------------------------------------
// reST -> HTML. Only the subset that appears in option docstrings: paragraphs,
// bullet lists, code blocks, inline literals/emphasis, and Sphinx roles.

export function escapeHtml(text) {
  return text
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;");
}

export function inline(text) {  let html = escapeHtml(text);
  html = html.replace(/``([^`]+)``/g, "<code>$1</code>");
  html = html.replace(/\*\*([^*]+)\*\*/g, "<strong>$1</strong>");
  html = html.replace(/:[\w-]+:`([^`]*)`/g, (_, inner) => {
    const labelled = /^(.*?)\s*&lt;(.*?)&gt;$/.exec(inner);
    const label = labelled ? labelled[1] : inner;
    return label.replaceAll("¶", "").trim();
  });
  html = html.replace(/\s*\(in configuration: <code>.*?<\/code>\)/g, "");
  return html.replace(/\s+/g, " ").trim();
}

function takeIndented(lines, start) {
  let end = start;
  while (end < lines.length && (isBlank(lines[end]) || indentOf(lines[end]) > 0)) end += 1;
  const block = trimBlanks(lines.slice(start, end));
  const width = block.filter((line) => !isBlank(line)).reduce(
    (min, line) => Math.min(min, indentOf(line)),
    Number.POSITIVE_INFINITY,
  );
  return { block: dedent(block, Number.isFinite(width) ? width : 0), next: end };
}

/**
 * Renders a dedented reST fragment. Unknown directives are dropped along with
 * their indented body; this keeps generated docs free of raw markup.
 */
export function renderDoc(lines) {
  const src = trimBlanks(lines);
  const out = [];
  let i = 0;

  while (i < src.length) {
    const line = src[i];
    if (isBlank(line)) {
      i += 1;
      continue;
    }
    const trimmed = line.trim();

    if (trimmed.startsWith(".. code-block::")) {
      const { block, next } = takeIndented(src, i + 1);
      out.push(`<pre><code>${escapeHtml(block.join("\n"))}</code></pre>`);
      i = next;
      continue;
    }

    const admonition = /^\.\. (note|warning|tip|important)::/.exec(trimmed);
    if (admonition) {
      const { block, next } = takeIndented(src, i + 1);
      out.push(`<div class="admonition ${admonition[1]}">${renderDoc(block)}</div>`);
      i = next;
      continue;
    }

    if (trimmed.startsWith(".. ")) {
      const { next } = takeIndented(src, i + 1);
      i = next;
      continue;
    }

    if (/^\* /.test(line)) {
      const items = [];
      while (i < src.length && /^\* /.test(src[i])) {
        const item = [src[i].replace(/^\* /, "")];
        i += 1;
        while (i < src.length && (isBlank(src[i]) || indentOf(src[i]) > 0)) {
          item.push(src[i]);
          i += 1;
        }
        items.push(trimBlanks(item));
        while (i < src.length && isBlank(src[i])) i += 1;
        if (i < src.length && !/^\* /.test(src[i])) break;
      }
      out.push(`<ul>${items.map((item) => `<li>${renderDoc(item)}</li>`).join("")}</ul>`);
      continue;
    }

    const paragraph = [];
    while (i < src.length && !isBlank(src[i]) && !src[i].trim().startsWith(".. ")) {
      paragraph.push(src[i].trim());
      i += 1;
    }
    if (paragraph.length === 0) {
      i += 1;
      continue;
    }
    out.push(`<p>${inline(paragraph.join(" "))}</p>`);
  }

  return out.join("\n");
}
